for m in range(M):
    for t in range(T):
        model.addConstr(gurobipy.quicksum(Time[p][m] * Manufacture[p][t] for p in range(P)) <= WorkHours * 2 * 24 * (NumMachines[m] - Maintain[m][t]), name=f"MachineCapacity_{m}_{t}")

for p in range(P):
    for t in range(T):
        model.addConstr(Sell[p][t] <= Limit[t][p], name=f"SalesLimit_{p}_{t}")

for p in range(P):
    for t in range(T):
        model.addConstr(Store[p][t] <= 100, name=f"StorageLimit_{p}_{t}")

for p in range(P):
    for t in range(T):
        if t == 0:
            model.addConstr(Store[p][t] == Manufacture[p][t] - Sell[p][t], name=f"Balance_{p}_{t}")
        else:
            model.addConstr(Store[p][t] == Store[p][t-1] + Manufacture[p][t] - Sell[p][t], name=f"Balance_{p}_{t}")

for m in range(M):
    for t in range(T):
        model.addConstr(Maintain[m][t] >= 0, name=f"MaintainNonNeg_{m}_{t}")
        model.addConstr(Maintain[m][t] <= NumMachines[m], name=f"MaintainMax_{m}_{t}")

for p in range(P):
    for t in range(T):
        model.addConstr(Sell[p][t] >= 0, name=f"NonNegSell_{p}_{t}")
        model.addConstr(Manufacture[p][t] >= 0, name=f"NonNegMfg_{p}_{t}")
        model.addConstr(Store[p][t] >= 0, name=f"NonNegStore_{p}_{t}")
